<?php
require __DIR__ . '/../lib/bootstrap.php';$user=auth_user();if($_SERVER['REQUEST_METHOD']!=='POST')fail('Method not allowed',405);$d=input();
$types=['Family Group','Friend Group','Fan Group','Study Group','College Group','Class Group','Department Group','Project Group','Club Group','Alumni Group','Workplace Group','Neighborhood Group','Event Group','Staff Group'];
$name=trim((string)($d['name']??''));$type=(string)($d['group_category']??'');$retention=(int)($d['retention_seconds']??0);$shortcut=!empty($d['shortcut']);if($name===''||!in_array($type,$types,true))fail('Valid group name and category are required');
$allowed=[0,86400,604800,1296000,2592000,7776000];if(!in_array($retention,$allowed,true))fail('Invalid retention policy');
$pdo=db();$pdo->beginTransaction();try{$st=$pdo->prepare('INSERT INTO chats(type,name,group_category,owner_id,retention_seconds,created_at) VALUES("group",?,?,?,?,UTC_TIMESTAMP())');$st->execute([$name,$type,$user['id'],$retention]);$chat=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO chat_members(chat_id,user_id,role,status,joined_at) VALUES(?,?,"owner","active",UTC_TIMESTAMP())')->execute([$chat,$user['id']]);$raw=random_token();$pdo->prepare('INSERT INTO group_invites(chat_id,token_hash,created_by,active,created_at) VALUES(?,SHA2(?,256),?,1,UTC_TIMESTAMP())')->execute([$chat,$raw,$user['id']]);if($shortcut)$pdo->prepare('INSERT INTO group_shortcuts(user_id,chat_id,display_order,created_at) VALUES(?,?,0,UTC_TIMESTAMP())')->execute([$user['id'],$chat]);$pdo->commit();out(['group'=>['id'=>$chat,'name'=>$name,'group_category'=>$type],'invite_url'=>$config['app']['base_url'].'/join.php?token='.urlencode($raw)],201);}catch(Throwable $e){$pdo->rollBack();fail('Group creation failed',500);}
